// 02_shadows — `.nxscene` parser.
//
// The format is line oriented on purpose. A parse error must point at the line
// that broke, because the file is generated by scripts/export_scene.py and a
// mismatch there is the first thing to check when the image looks wrong.

#include "scene.h"

#include <cmath>
#include <fstream>
#include <sstream>
#include <utility>

namespace nx::shadow {
namespace {

std::string location(const std::string& path, int line) {
    return path + ":" + std::to_string(line) + ": ";
}

bool parse_doubles(std::istringstream& stream, int count, double* values,
                   const std::string& path, int line, const char* what,
                   std::string* error) {
    for (int i = 0; i < count; ++i) {
        if (!(stream >> values[i]) || !std::isfinite(values[i])) {
            *error = location(path, line) + "expected " + std::to_string(count) +
                     " finite numbers for " + what + ", failed at value " +
                     std::to_string(i);
            return false;
        }
    }
    return true;
}

Vec3 finite_vec3(double x, double y, double z) {
    return {static_cast<float>(x), static_cast<float>(y), static_cast<float>(z)};
}

}  // namespace

Vec3 Light::polygon_normal() const {
    return normalize(cross(corners[1] - corners[0], corners[2] - corners[0]));
}

float Light::area() const {
    const float first = length(cross(corners[1] - corners[0], corners[2] - corners[0]));
    const float second = length(cross(corners[2] - corners[0], corners[3] - corners[0]));
    return 0.5f * (first + second);
}

Mat4 Camera::view() const {
    return view_from_basis(origin, right, up, forward);
}

Mat4 Camera::projection() const {
    return perspective(fov_x, fov_y, near_plane, far_plane);
}

Mat4 Camera::view_projection() const {
    return projection() * view();
}

void Camera::set_resolution(int width_value, int height_value) {
    if (width_value <= 0 || height_value <= 0) {
        return;
    }
    width = width_value;
    height = height_value;
    const float tan_half_x = std::tan(radians(fov_x) * 0.5f);
    fov_y = degrees(2.0f * std::atan(tan_half_x * static_cast<float>(height) /
                                     static_cast<float>(width)));
}

std::size_t Scene::triangle_count() const {
    std::size_t count = 0;
    for (const Mesh& mesh : meshes) {
        count += mesh.triangles.size();
    }
    return count;
}

const Light* Scene::primary_light() const {
    return lights.empty() ? nullptr : &lights.front();
}

bool load_nxscene(const std::string& path, Scene* scene, std::string* error) {
    std::ifstream file(path);
    if (!file) {
        *error = "cannot open " + path + " (run scripts/export_scene.py to create it)";
        return false;
    }

    Scene result;
    bool saw_header = false;
    std::string line;
    int line_number = 0;

    while (std::getline(file, line)) {
        ++line_number;
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
        if (line.empty()) {
            continue;
        }
        if (line[0] == '#') {
            static const std::string kSource = "# source: ";
            static const std::string kMtime = "# source_mtime: ";
            if (line.rfind(kSource, 0) == 0) {
                result.source_path = line.substr(kSource.size());
            } else if (line.rfind(kMtime, 0) == 0) {
                std::istringstream value(line.substr(kMtime.size()));
                value >> result.source_mtime;
            }
            continue;
        }

        std::istringstream stream(line);
        std::string token;
        if (!(stream >> token)) {
            continue;
        }

        if (token == "nxscene") {
            int version = 0;
            if (!(stream >> version) || version != 1) {
                *error = location(path, line_number) + "unsupported .nxscene version";
                return false;
            }
            saw_header = true;
            continue;
        }

        if (!saw_header) {
            *error = location(path, line_number) + "missing 'nxscene 1' header";
            return false;
        }

        if (token == "film") {
            if (!(stream >> result.camera.width >> result.camera.height) ||
                result.camera.width <= 0 || result.camera.height <= 0) {
                *error = location(path, line_number) + "invalid film size";
                return false;
            }
            continue;
        }

        if (token == "camera") {
            double values[16] = {};
            if (!parse_doubles(stream, 16, values, path, line_number, "camera", error)) {
                return false;
            }
            result.camera.origin = finite_vec3(values[0], values[1], values[2]);
            result.camera.right = normalize(finite_vec3(values[3], values[4], values[5]));
            result.camera.up = normalize(finite_vec3(values[6], values[7], values[8]));
            result.camera.forward = normalize(finite_vec3(values[9], values[10], values[11]));
            result.camera.fov_x = static_cast<float>(values[12]);
            result.camera.fov_y = static_cast<float>(values[13]);
            result.camera.near_plane = static_cast<float>(values[14]);
            result.camera.far_plane = static_cast<float>(values[15]);

            const float basis_dot = std::fabs(dot(result.camera.right, result.camera.forward)) +
                                    std::fabs(dot(result.camera.right, result.camera.up)) +
                                    std::fabs(dot(result.camera.up, result.camera.forward));
            if (basis_dot > 1e-3f) {
                *error = location(path, line_number) + "camera basis is not orthogonal";
                return false;
            }
            if (!(result.camera.fov_x > 0.0f && result.camera.fov_y > 0.0f) ||
                !(result.camera.near_plane > 0.0f &&
                  result.camera.near_plane < result.camera.far_plane)) {
                *error = location(path, line_number) + "invalid camera fov or clip planes";
                return false;
            }
            continue;
        }

        if (token == "light") {
            std::string kind;
            if (!(stream >> kind)) {
                *error = location(path, line_number) + "light is missing its kind";
                return false;
            }
            if (kind == "directional") {
                double values[6] = {};
                if (!parse_doubles(stream, 6, values, path, line_number, "directional light",
                                   error)) {
                    return false;
                }
                Light light;
                light.kind = Light::Kind::Directional;
                light.direction = normalize(finite_vec3(values[0], values[1], values[2]));
                light.irradiance = finite_vec3(values[3], values[4], values[5]);
                result.lights.push_back(light);
            } else if (kind == "area") {
                double values[15] = {};
                if (!parse_doubles(stream, 15, values, path, line_number, "area light",
                                   error)) {
                    return false;
                }
                Light light;
                light.kind = Light::Kind::Area;
                light.radiance = finite_vec3(values[0], values[1], values[2]);
                for (int corner = 0; corner < 4; ++corner) {
                    const int base = 3 + corner * 3;
                    light.corners[corner] =
                        finite_vec3(values[base], values[base + 1], values[base + 2]);
                }
                result.lights.push_back(light);
            } else {
                *error = location(path, line_number) + "unknown light kind '" + kind + "'";
                return false;
            }
            continue;
        }

        if (token == "mesh") {
            Mesh mesh;
            double albedo[3] = {};
            std::size_t triangle_count = 0;
            if (!parse_doubles(stream, 3, albedo, path, line_number, "mesh albedo", error)) {
                return false;
            }
            if (!(stream >> triangle_count)) {
                *error = location(path, line_number) + "mesh is missing its triangle count";
                return false;
            }
            mesh.albedo = finite_vec3(albedo[0], albedo[1], albedo[2]);
            mesh.triangles.reserve(triangle_count);

            for (std::size_t index = 0; index < triangle_count; ++index) {
                std::string triangle_line;
                if (!std::getline(file, triangle_line)) {
                    *error = location(path, line_number) + "file ended inside a mesh";
                    return false;
                }
                ++line_number;
                if (!triangle_line.empty() && triangle_line.back() == '\r') {
                    triangle_line.pop_back();
                }
                std::istringstream triangle_stream(triangle_line);
                std::string triangle_token;
                if (!(triangle_stream >> triangle_token) || triangle_token != "tri") {
                    *error = location(path, line_number) + "expected a 'tri' line, got '" +
                             triangle_line.substr(0, 32) + "'";
                    return false;
                }
                double values[18] = {};
                if (!parse_doubles(triangle_stream, 18, values, path, line_number,
                                   "triangle", error)) {
                    return false;
                }
                Triangle triangle;
                for (int vertex = 0; vertex < 3; ++vertex) {
                    // A `tri` line is p0 p1 p2 n0 n1 n2, not interleaved.
                    const int position_base = vertex * 3;
                    const int normal_base = 9 + vertex * 3;
                    triangle.position[vertex] =
                        finite_vec3(values[position_base], values[position_base + 1],
                                    values[position_base + 2]);
                    triangle.normal[vertex] = normalize(
                        finite_vec3(values[normal_base], values[normal_base + 1],
                                    values[normal_base + 2]));
                }
                mesh.triangles.push_back(triangle);
            }

            if (!mesh.triangles.empty()) {
                result.meshes.push_back(std::move(mesh));
            }
            continue;
        }

        *error = location(path, line_number) + "unknown token '" + token + "'";
        return false;
    }

    if (!saw_header) {
        *error = path + ": missing 'nxscene 1' header";
        return false;
    }
    if (result.meshes.empty()) {
        *error = path + ": no geometry";
        return false;
    }
    if (result.camera.width <= 0 || result.camera.height <= 0) {
        *error = path + ": no film size";
        return false;
    }

    for (const Mesh& mesh : result.meshes) {
        for (const Triangle& triangle : mesh.triangles) {
            for (const Vec3& position : triangle.position) {
                result.bounds.expand(position);
            }
        }
    }

    *scene = std::move(result);
    return true;
}

}  // namespace nx::shadow
